contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        address spender,
        address to,
        uint256 approveAmt,
        uint256 amount
    ) public {
        require(spender != address(0));
        require(to != address(0));

        // Approve an arbitrary allowance for an arbitrary spender.
        c.approve(spender, approveAmt); if (__ESBMC_reverted()) return;

        // Snapshot balances/allowance before the deciding call.
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 allowBefore = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        // transferFrom from our own balance (fresh pool: balance is 0).
        bool reverted;
        c.transferFrom(address(this), to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: transferFrom must revert exactly when the amount
        // exceeds the sender's share balance OR the granted allowance.
        assert(reverted == (amount > balBefore || amount > allowBefore));
    }

    receive() external payable {}
}

